/** The pocket moved `dx` Å along x, as a second copy to superpose. */
export function shiftedPocket(dx: number) {
  return POCKET_MMCIF.split('\n')
    .map(line => {
      if (!/^(ATOM|HETATM) /.test(line)) {
        return line
      }
      const fields = line.split(' ')
      fields[10] = (Number(fields[10]) + dx).toFixed(3)
      return fields.join(' ')
    })
    .join('\n')
}
